<?php namespace App\Filament\Resources\ProjectResource\Pages; use App\Filament\Resources\ProjectResource; use App\Services\ProjectPlanningService; use Filament\Actions; use Filament\Notifications\Notification; use Filament\Resources\Pages\ViewRecord; use Illuminate\Auth\Access\AuthorizationException; use Illuminate\Validation\ValidationException; class ViewProject extends ViewRecord {protected static string $resource=ProjectResource::class; protected function getHeaderActions():array{return [Actions\Action::make('approve')->visible(fn()=>$this->record->status==='planning')->authorize('approve')->action(fn()=>$this->transition('approved','Project Approved')),Actions\Action::make('start')->visible(fn()=>$this->record->status==='approved')->authorize('update')->action(fn()=>$this->transition('in_progress','Project Started')),Actions\Action::make('complete')->visible(fn()=>$this->record->status==='in_progress')->authorize('update')->action(fn()=>$this->transition('completed','Project Completed')),Actions\Action::make('close')->visible(fn()=>$this->record->status==='completed')->authorize('close')->action(fn()=>$this->transition('closed','Project Closed')),Actions\Action::make('cancel')->visible(fn()=>in_array($this->record->status,['planning','approved','in_progress']))->authorize('cancel')->form([\Filament\Forms\Components\Textarea::make('reason')->required()])->action(fn(array $data)=>$this->transition('cancelled','Project Cancelled',$data['reason']))];} private function transition(string $to,string $title,?string $reason=null):void{try{$this->record=app(ProjectPlanningService::class)->transitionProject(auth()->user(),$this->record,$to,$reason);Notification::make()->success()->title($title)->body('Current status: '.str_replace('_',' ',$to).'.')->send();}catch(ValidationException $e){Notification::make()->danger()->title('Cannot change project status')->body(collect($e->errors())->flatten()->first())->send();}catch(AuthorizationException){Notification::make()->danger()->title('Unauthorized')->send();}}}
